import { Link, useNavigate } from 'react-router-dom';
import Header from '../Home/Header';
import {ListingContainer,SearchContainer,BodyListing} from './styles';
import {BsSearch} from 'react-icons/bs';
import { useEffect, useState } from 'react';
import { PropertyPage } from '../../types/property';
import { BASE_URL } from '../../utils/requests';
import axios from 'axios';
import PropertySite from '../Home/PropertySite';
import Pagination from '../../components/Pagination';



const Listing = () => {

   
    
    const [pageNumber, setPageNumber] = useState(0);

    

    const [page, setPage] = useState<PropertyPage>({

        content: [],
        last: true,
        totalPages: 0,
        totalElements: 0,
        size: 12,
        number: 0,
        first: true,
        numberOfElements: 0,
        empty: true
    });
    const [busca, setBusca] = useState('');

    const propsFilters=page.content
    .filter((prop) => prop.startsWith(busca));

    useEffect(() => {
        axios.get(`${BASE_URL}/properties?size=12&page=${pageNumber}&sort=title`)
            .then(response => {
                const data = response.data as PropertyPage;
                setPage(data)

            });

    }, [pageNumber]);

    const handlePageChange = (newPageNumber : number)=>{
        setPageNumber(newPageNumber);
    }

    const navigate = useNavigate();


    const handleToSignIn = () =>{
        navigate('/details');
    }
    
    return (
     <ListingContainer>
         <Header />
         <SearchContainer>
         <input type='text' placeholder='city, county, state' value={busca} onChange={(ev) => setBusca(ev.target.value)}/>
                <button type='submit'><BsSearch /> </button>
         </SearchContainer>
         <BodyListing>
           
         {propsFilters.map(property => (
                            <div className='wrapper-property'>
                            <PropertySite  key={property.id} property={property}/>
                            </div>
                      
                    )

                    )}
                
                
         </BodyListing>
         <Pagination page={page} onChange={handlePageChange}/>
     </ListingContainer>
    )
}

export default Listing
